import 'package:yaml/yaml.dart';

/// The app's public identity, read from `config/app_identity.yaml`.
class AppIdentity {
  const AppIdentity({
    required this.displayName,
    required this.androidApplicationId,
    required this.iosBundleId,
  });

  final String displayName;
  final String androidApplicationId;
  final String iosBundleId;
}

/// Where the generated platform files live, relative to the project root.
const androidPropertiesPath = 'android/app/identity.properties';
const iosXcconfigPath = 'ios/Flutter/AppIdentity.xcconfig';

const _generatedHeader =
    'GENERATED by tool/set_app_identity.dart from '
    'config/app_identity.yaml. Do not edit by hand.';

/// IDs under this prefix are placeholders and must not ship.
const placeholderPrefix = 'com.example';

/// Parses the identity YAML. Throws [FormatException] when a key is missing
/// or is not a non-empty string.
AppIdentity parseAppIdentity(String source) {
  final Object? doc = loadYaml(source);
  if (doc is! YamlMap) {
    throw const FormatException('app_identity.yaml must be a YAML map.');
  }
  String read(String key) {
    final value = doc[key];
    if (value is! String || value.trim().isEmpty) {
      throw FormatException('"$key" must be a non-empty string.');
    }
    return value.trim();
  }

  return AppIdentity(
    displayName: read('displayName'),
    androidApplicationId: read('androidApplicationId'),
    iosBundleId: read('iosBundleId'),
  );
}

final _androidId = RegExp(r'^[A-Za-z][A-Za-z0-9_]*(\.[A-Za-z][A-Za-z0-9_]*)+$');
final _iosId = RegExp(r'^[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$');

// Characters that would need escaping in Android string resources, Java
// properties or xcconfig files. A display name never needs them.
final _unsafeDisplayChars = RegExp(r'''[&<>"'\\@?$/=:#!;]''');

/// Returns the problems with [identity]; an empty list means it is valid.
/// With [release], placeholder IDs are also rejected.
List<String> validateAppIdentity(AppIdentity identity, {bool release = false}) {
  final errors = <String>[];
  if (_unsafeDisplayChars.hasMatch(identity.displayName)) {
    errors.add(
      'displayName contains a character that is not allowed: '
      '${_unsafeDisplayChars.firstMatch(identity.displayName)![0]}',
    );
  }
  if (!_androidId.hasMatch(identity.androidApplicationId)) {
    errors.add(
      'androidApplicationId "${identity.androidApplicationId}" is not '
      'a valid Android application ID.',
    );
  }
  if (!_iosId.hasMatch(identity.iosBundleId)) {
    errors.add(
      'iosBundleId "${identity.iosBundleId}" is not a valid iOS '
      'bundle ID (letters, digits, "-" and "." only).',
    );
  }
  if (release) {
    for (final (key, id) in [
      ('androidApplicationId', identity.androidApplicationId),
      ('iosBundleId', identity.iosBundleId),
    ]) {
      if (id == placeholderPrefix || id.startsWith('$placeholderPrefix.')) {
        errors.add(
          '$key "$id" is a placeholder; set the final ID before a '
          'release build.',
        );
      }
    }
  }
  return errors;
}

/// Contents of [androidPropertiesPath]. Gradle reads it as UTF-8.
String renderAndroidProperties(AppIdentity identity) =>
    '''
# $_generatedHeader
applicationId=${identity.androidApplicationId}
appName=${identity.displayName}
''';

/// Contents of [iosXcconfigPath], included by Debug and Release xcconfigs.
String renderIosXcconfig(AppIdentity identity) =>
    '''
// $_generatedHeader
APP_BUNDLE_ID = ${identity.iosBundleId}
APP_DISPLAY_NAME = ${identity.displayName}
''';
